# BW1000 标定值（实测可达，来自 machines/gfx936-bw1000.json） BW_HBM = 1.339e12 # B/s PEAK = {"bf16_mmac": 476.0e12, "tf32_mmac": 237.7e12, "fp32_mmac": 61.0e12, "fp32_valu": 29.7e12}
def place(flops, dram_bytes, seconds, roof="bf16_mmac"): I = flops / dram_bytes # 计算强度（实现） perf = flops / seconds # 实际性能 FLOP/s bw = dram_bytes / seconds # 实际带宽 B/s attainable = min(PEAK[roof], BW_HBM * I) # 该强度下的上限 return dict(I=round(I, 1), TFLOPS=round(perf / 1e12, 1), MFU=round(perf / PEAK[roof], 3), MBU=round(bw / BW_HBM, 3), to_roof=round(perf / attainable, 3), ridge=round(PEAK[roof] / BW_HBM))
# KDA 前向+反向，16K 序列、TP8（每卡 12 个 head） print(place(99.1e9, 4.722e9, 5.32e-3)) # {'I': 21.0, 'TFLOPS': 18.6, 'MFU': 0.039, 'MBU': 0.663, 'to_roof': 0.663, 'ridge': 355}
